Definition LIT_CLMAX : list Z := [153; 153; 153; 153; 153; 153; 153; 25].
Lemma clmax_bytes : forall m, mem_inv usegs m -> ro_cells usegs m A_CLMAX10 [CB 8 (litb LIT_CLMAX)].
Proof.
  intros m MI.
  apply (ro_cells_image usegs m); [exact MI | vm_compute; reflexivity | unfold A_CLMAX10; lia | cbn; unfold A_CLMAX10; lia].
Qed.
