(* [comment removed for export] *)
Lemma cl_commas0 : forall rax spx gp tp t0 t1 t2 s0 s1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp : Z) (vbs : list byte),
  bytes_at usegs m1 vp vbs -> mem_inv usegs m1 -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp -> Z.of_nat (length vbs) < 2^32 -> (1 <= length vbs)%nat ->
  evt usegs (fun ms' => exists a0' a5' a6' a7' cnt',
      ms' = MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz cnt') (wz 44) a2 a3 (Z_to_bv 64 (-1)) a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 0x3f658) fc None m1 (seg_rom usegs)
      /\ 0 <= cnt' <= Z.of_nat (length vbs) /\ a0' = wz cnt')
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz 0) (wz 44) a2 a3 (Z_to_bv 64 (-1)) (wz (Z.of_nat (length vbs))) (wz vp) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f630) fc None m1 (seg_rom usegs)).
Proof.
  intros until vbs. intros WIN MI V3 NZ VLEN L1.
  pose proof (cl_commas (length vbs) 0 0 rax spx gp tp t0 t1 t2 s0 s1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vbs
                WIN MI V3 NZ VLEN ltac:(lia) ltac:(lia) L1 ltac:(lia)) as K.
  rewrite !Z.add_0_r in K. exact K.
Qed.

