(* [comment removed for export] *)
Lemma cl_digits0 : forall (vl : Z) rax spx gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at usegs m1 vp vbs -> mem_inv usegs m1 -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  vp <= vq -> 1 <= vl -> vq + vl <= vp + Z.of_nat (length vbs) ->
  evt usegs (dig_post rax spx gp tp t0 t1 t2 s0 s1 a0 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz vq) (wz vl) (wz 0) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f7b0) fc None m1 (seg_rom usegs)).
Proof.
  intros until vbs. intros WIN MI V3 NZ V1 VL VB.
  pose proof (cl_digits (Z.to_nat vl) 0 0 rax spx gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vq vbs
                WIN MI V3 NZ V1 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)) as K.
  rewrite Z2Nat.id in K by lia. rewrite !Z.add_0_r in K. exact K.
Qed.


