Section CL.

Local Ltac dof_finish c' E' g' :=
  apply evt_done; unfold dof_post;
  do 16 eexists; exists c', E', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

(* [comment removed for export] *)
Definition cl_ctx (m m1 : mem) (sp : word) (sv : list word) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte)
    (vp : Z) (vbs : list byte) (j0 : list byte) (t40c : list cell) (jm : list byte) (hv : bool) (padx : list byte) (xv : Z)
    (optc : list cell) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -288) [CB 40 j0]
  /\ rw_cells usegs m1 (bv_unsigned sp + -248) t40c
  /\ rw_cells usegs m1 (bv_unsigned sp + -224) [CB 96 jm]
  /\ rw_cells usegs m1 (bv_unsigned sp + -128) (OptU64Cells hv padx (wz xv))
  /\ rw_cells usegs m1 (bv_unsigned sp + -112) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))]
  /\ rw_cells usegs m1 (bv_unsigned sp + -96) [C8 (wz E)]
  /\ rw_cells usegs m1 (bv_unsigned sp + -88) optc
  /\ rw_cells usegs m1 (bv_unsigned sp + -48) (map C8 sv)
  /\ rw_cells usegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells usegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at usegs m1 vp vbs
  /\ HttpCat m1 g /\ XStatics m1
