(* [comment removed for export] *)
Lemma cl_succ : forall (t40c optc : list cell) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j0 jm padx : list byte) (xv : Z) (e1 e2 e3 : word) (g : bool),
  cl_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs j0 t40c jm true padx xv optc e1 e2 e3 g ->
  cells_size t40c = 24%nat -> cells_size optc = 40%nat ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= xv < 2^64 ->
  evt usegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
