(* [comment removed for export] *)
Definition CL_AT (mu : nat) : Prop :=
  forall (itc vq vl err cnt xv : Z) (hv : bool) (t40c : list cell) rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 (s4x : word) s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j0 jm padx pad7o : list byte) (e1 e2 e3 : word) (g : bool),
  cl_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs j0 t40c jm hv padx xv
         (OptItCells (bv_unsigned sp + -112) itc vq vl err pad7o) e1 e2 e3 g ->
  cells_size t40c = 24%nat ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= err < 2 -> 0 <= xv < 2^64 ->
  vp <= vq -> 1 <= vl -> vq + vl = itc -> itc <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) - itc < Z.of_nat mu ->
  1 <= cnt + (vq - vp) -> cnt <= 2^32 -> (hv = false -> 1 <= cnt) ->
